{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "C05 reports F=0.15 for furosemide acyl glucuronide, a metabolite, not for the parent furosemide; this low value is not a direct measure of the query's oral bioavailability and is weak contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C38"],
      "claim": "Azosemide, a close structural analogue with a tetrazole replacing the carboxylate, has absolute oral bioavailability of ~20.4% in fasting healthy humans, providing some transferable evidence for low F; however, the structural difference and fasting condition limit its weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C28"],
      "claim": "Bumetanide, a structurally related sulfamoylbenzoic acid loop diuretic, has measured oral bioavailability of 59–89% (median ~80%) in healthy volunteers, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Tolfenamic acid, an anthranilic acid derivative, has absolute oral bioavailability of ~60% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Hydrochlorothiazide, a sulfonamide diuretic, has oral bioavailability of 66–75% in healthy adults, supporting high F for this sulfonamide-containing query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: furosemide is expected to have absolute oral bioavailability ≥20%. The low metabolite value (C05) is not a parent-F measurement, and azosemide's borderline low F is only moderately transferable. Multiple close analogues with sulfonamide/anthranilic acid structures (bumetanide, tolfenamic acid, hydrochlorothiazide) show F well above 20%, supporting high bioavailability.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the parent furosemide under fed conditions is present; the closest record (C05) is for the acyl glucuronide metabolite.",
    "Azosemide low-bioavailability data were obtained in the fasting state and may not reflect the fed-state condition of the query.",
    "The retrieved evidence does not include a fed-state furosemide-specific pharmacokinetic study, so the effect of food on F is inferred indirectly."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "not_applicable",
      "card_ids": [],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "none"
    }
  ],
  "revision_action": "initial"
}

